'use client'

import * as React from 'react'

import { useStrings, type StringsOverrides } from './strings'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Reactions, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './reactions.css'

// The shared rule sets, so the theme's action face and press gesture reach the
// pills and the picker. GSUI-118: the file shipped with the tokens and nothing
// imported it, so the classes matched nothing in a real install.
import './gamestage-primitives.css'

/**
 * Reactions: what a room says about one message without typing.
 *
 * Specimen 6h. Pills sit under the message and count up, the one the reader
 * pressed is filled, and the row adds its height to the message once and never
 * again, because the set of emotes is fixed: a fifth emote cannot arrive and
 * push the stream.
 *
 * The picker floats over the stream and reflows nothing. That is the whole
 * reason it is positioned rather than mounted in the column: a picker that
 * arrived in flow would push every message under it down at the moment the
 * reader is aiming at one, which is the second rule in
 * `docs/mobile-game-frame.md`. The long press that opens it belongs to the
 * host, because the gesture lands on the message and the message is a
 * different component.
 *
 * The emotes are the host's, the same four specimen 4h floats. The library
 * ships none and names none: an emote is a label and an optional shape the
 * host hands over. There is no free text here, so nothing in this control
 * needs screening, and nothing in it is ranked, stored or counted by the
 * library. A press that adds a reaction and a press that takes it back are the
 * same press, the same way a vote is.
 */

export interface ReactionEmote {
  /** The host's own id, used as the attribute value and as the React key. */
  id: string
  /** What it is called, in words. The accessible name, and the pill's text. */
  label: string
  /**
   * A shape drawn instead of the label, for an emote with no word: specimen
   * 4h's heart. The label still names it for anybody reading it out.
   */
  mark?: React.ReactNode
  /** How many people pressed it. Host-owned; the library counts nothing. */
  count?: number
  /** The reader is one of them. The same press takes it back. */
  reacted?: boolean
}

export interface ReactionsProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** The fixed set, in the order the host wants them read. */
  emotes: ReactionEmote[]
  /** A pill was pressed. Adding and taking back are the same press. */
  onReact?: (id: string) => void

  /**
   * The picker is open. The host sets it from the long press on the message,
   * because the gesture lands on the message rather than here.
   */
  picking?: boolean
  /** An emote was chosen from the picker. */
  onPick?: (id: string) => void

  /** What the row is, for anybody reading it out. */
  label?: string
}

export function Reactions(props: ReactionsProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)

  const {
    emotes,
    onReact,
    picking = false,
    onPick,
    label = copy['reactions.label'],
    className,
    children,
    ...rest
  } = componentProps

  // A pill for an emote nobody has pressed would be a row of four empty
  // controls under every message in the room. The picker is where the
  // unpressed ones live.
  const shown = emotes.filter(emote => (emote.count ?? 0) > 0 || emote.reacted === true)

  if (shown.length === 0 && !picking) return null

  const name = (emote: ReactionEmote) => {
    const counted = copy['reactions.reaction'](emote.label, emote.count ?? 0)
    return emote.reacted === true ? copy['reactions.reactionYours'](counted, copy['reactions.yours']) : counted
  }

  return (
    <div
      {...rest}
      className={['gs-reactions', className].filter(Boolean).join(' ')}
      data-gs-component="reactions"
      data-gs-presentation="pills"
      role="group"
      aria-label={label}
    >
      {shown.length > 0 ? (
        <div className="gs-reactions__row" data-gs-scope="reactions" data-gs-part="actions">
          {shown.map(emote => (
            <button
              key={emote.id}
              type="button"
              className="gs-reactions__pill gs-action-type gs-pressable"
              data-gs-scope="reactions" data-gs-part="control"
              data-gs-reaction={emote.id}
              data-gs-count={emote.count ?? 0}
              data-gs-selected={emote.reacted === true ? 'true' : undefined}
              aria-pressed={emote.reacted === true}
              aria-label={name(emote)}
              onClick={() => onReact?.(emote.id)}
            >
              <span className="gs-reactions__mark" aria-hidden="true">
                {emote.mark ?? emote.label}
              </span>
              <span
                className="gs-reactions__count"
                data-gs-scope="reactions" data-gs-part="value"
                aria-hidden="true"
              >
                {emote.count ?? 0}
              </span>
            </button>
          ))}
        </div>
      ) : null}

      {/* Over the stream, never in it. Absolutely positioned against this row,
          so opening it moves no message. */}
      {picking ? (
        <div
          className="gs-reactions__picker"
          data-gs-scope="reactions" data-gs-part="panel"
          data-gs-animates="motion"
          data-gs-motion="pop"
          role="group"
          aria-label={copy['reactions.pickLabel']}
        >
          {emotes.map(emote => (
            <button
              key={emote.id}
              type="button"
              className="gs-reactions__choice gs-action-type gs-pressable"
              data-gs-scope="reactions" data-gs-part="control"
              data-gs-reaction={emote.id}
              data-gs-selected={emote.reacted === true ? 'true' : undefined}
              aria-pressed={emote.reacted === true}
              aria-label={emote.label}
              onClick={() => onPick?.(emote.id)}
            >
              <span className="gs-reactions__mark" aria-hidden="true">
                {emote.mark ?? emote.label}
              </span>
            </button>
          ))}
        </div>
      ) : null}

      {children}
    </div>
  )
}

/* Reactions. Every value comes from a token; nothing here is a literal colour.

   Specimen 6h draws a 28px pill row under the bubble and a 44px picker on a
   raised pill floating over the stream. The row's height is the one thing a
   message gains from having reactions, and it gains it once: the set of
   emotes is fixed, so a row of four is the widest this ever gets and it never
   wraps a message into a second line of pills. */

.gs-reactions {
  /* The picker is positioned against this, which is what keeps it out of the
     column. */
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-1);
}

.gs-reactions__row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--gs-space-1);
}

/* -- a pill -----------------------------------------------------------------

   28px is under the 44px floor on purpose and the drawing draws it that way:
   a reaction pill is a readout first, pressable second, and four of them at
   44px under every message would be a control bar rather than a tally. The
   picker is where the full-size targets are. */

.gs-reactions__pill {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-1);
  box-sizing: border-box;
  height: var(--gs-size-chip);
  padding: 0 var(--gs-space-2);
  cursor: pointer;

  font-size: var(--gs-type-caption-font-size);
  line-height: 1;

  color: var(--gs-color-ink-secondary);
  background: var(--gs-color-edge);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  transition:
    background var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis),
    color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis),
    border-color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

/* The reader's own. Filled and outlined, where the rest are flat: two changes
   rather than one, so it is still the pressed one with the colour taken
   away. */
.gs-reactions__pill[data-gs-selected='true'] {
  color: var(--gs-color-ink);
  background: var(--gs-color-positive-base);
  border-color: var(--gs-color-edge-high);
}

.gs-reactions__count {
  font-variant-numeric: tabular-nums;
  color: var(--gs-color-ink-secondary);
}

.gs-reactions__pill[data-gs-selected='true'] .gs-reactions__count {
  color: var(--gs-color-ink);
}

/* -- the picker -------------------------------------------------------------

   Absolute, so it takes no room in the column and the stream under it does
   not move. It rises from the row rather than covering it, which is where the
   drawing puts it. */

.gs-reactions__picker {
  position: absolute;
  inset-block-end: 100%;
  inset-inline-start: 0;
  z-index: 1;

  display: flex;
  gap: var(--gs-space-2);
  margin-block-end: var(--gs-space-1);
  padding: var(--gs-space-1);
  width: max-content;

  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge-high);
  border-radius: var(--gs-radius-full);
  box-shadow: var(--gs-depth-floating);
}

/* Full size here, because this is where a player aims. */
.gs-reactions__choice {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-sizing: border-box;
  width: var(--gs-size-touch-min);
  height: var(--gs-size-touch-min);
  padding: 0;
  cursor: pointer;

  font-size: var(--gs-type-caption-font-size);
  line-height: 1;

  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
}

.gs-reactions__choice[data-gs-selected='true'] {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-positive);
}

.gs-reactions__mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}
